SET 'execution.runtime-mode' = 'BATCH';
SET 'table.dml-sync' = 'true';
CREATE TEMPORARY VIEW row_column_source AS SELECT CAST('1' AS BIGINT) AS `group_id`, CAST('1' AS BIGINT) AS `seq`, CAST('sale' AS STRING) AS `code`, CAST('10.0000' AS DECIMAL(20,4)) AS `amount`, CAST('0.0000' AS DECIMAL(20,4)) AS `other`, CAST('first' AS STRING) AS `raw`, CAST('2026-11-01' AS STRING) AS `day`, CAST(TRUE AS BOOLEAN) AS `flag` UNION ALL SELECT CAST('1' AS BIGINT) AS `group_id`, CAST('2' AS BIGINT) AS `seq`, CAST('sale' AS STRING) AS `code`, CAST('20.0000' AS DECIMAL(20,4)) AS `amount`, CAST('0.0000' AS DECIMAL(20,4)) AS `other`, CAST('second' AS STRING) AS `raw`, CAST('missing' AS STRING) AS `day`, CAST(FALSE AS BOOLEAN) AS `flag` UNION ALL SELECT CAST('1' AS BIGINT) AS `group_id`, CAST('3' AS BIGINT) AS `seq`, CAST('cost' AS STRING) AS `code`, CAST('0.0000' AS DECIMAL(20,4)) AS `amount`, CAST('2.0000' AS DECIMAL(20,4)) AS `other`, CAST('third' AS STRING) AS `raw`, CAST('missing' AS STRING) AS `day`, CAST(TRUE AS BOOLEAN) AS `flag` UNION ALL SELECT CAST('1' AS BIGINT) AS `group_id`, CAST('4' AS BIGINT) AS `seq`, CAST('cost' AS STRING) AS `code`, CAST('0.0000' AS DECIMAL(20,4)) AS `amount`, CAST('4.0000' AS DECIMAL(20,4)) AS `other`, CAST('final' AS STRING) AS `raw`, CAST('missing' AS STRING) AS `day`, CAST(FALSE AS BOOLEAN) AS `flag` UNION ALL SELECT CAST('1' AS BIGINT) AS `group_id`, CAST('5' AS BIGINT) AS `seq`, CAST('date' AS STRING) AS `code`, CAST('0.0000' AS DECIMAL(20,4)) AS `amount`, CAST('0.0000' AS DECIMAL(20,4)) AS `other`, CAST('ignore' AS STRING) AS `raw`, CAST('2026-11-03' AS STRING) AS `day`, CAST(TRUE AS BOOLEAN) AS `flag` UNION ALL SELECT CAST('2' AS BIGINT) AS `group_id`, CAST('6' AS BIGINT) AS `seq`, CAST('sale' AS STRING) AS `code`, CAST('5.0000' AS DECIMAL(20,4)) AS `amount`, CAST('0.0000' AS DECIMAL(20,4)) AS `other`, CAST('only' AS STRING) AS `raw`, CAST('missing' AS STRING) AS `day`, CAST(TRUE AS BOOLEAN) AS `flag` UNION ALL SELECT CAST('2' AS BIGINT) AS `group_id`, CAST('7' AS BIGINT) AS `seq`, CAST('date' AS STRING) AS `code`, CAST('0.0000' AS DECIMAL(20,4)) AS `amount`, CAST('0.0000' AS DECIMAL(20,4)) AS `other`, CAST('ignored' AS STRING) AS `raw`, CAST('missing' AS STRING) AS `day`, CAST(FALSE AS BOOLEAN) AS `flag`;
CREATE TEMPORARY TABLE row_column_target (`group_id` BIGINT, `seq` BIGINT, `code` STRING, `day` STRING, `flag` BOOLEAN, `metric` STRING, `value` DECIMAL(20,4), `text` STRING) WITH ('connector'='filesystem','path'='/tmp/row-column/result','format'='json');
INSERT INTO `row_column_target` (`group_id`, `seq`, `code`, `day`, `flag`, `metric`, `value`, `text`) SELECT `group_id`, `seq`, `code`, `day`, `flag`, `metric`, `value`, `text` FROM (SELECT `group_id` AS `group_id`, `seq` AS `seq`, `code` AS `code`, `day` AS `day`, `flag` AS `flag`, 'sale''s' AS `metric`, `amount` AS `value`, CAST(NULL AS STRING) AS `text` FROM (SELECT `group_id`, `seq`, `code`, `amount`, `other`, `raw`, `day`, `flag` FROM `row_column_source`) dh_unpivot_input UNION ALL SELECT `group_id` AS `group_id`, `seq` AS `seq`, `code` AS `code`, `day` AS `day`, `flag` AS `flag`, 'cost' AS `metric`, `other` AS `value`, CAST(NULL AS STRING) AS `text` FROM (SELECT `group_id`, `seq`, `code`, `amount`, `other`, `raw`, `day`, `flag` FROM `row_column_source`) dh_unpivot_input UNION ALL SELECT `group_id` AS `group_id`, `seq` AS `seq`, `code` AS `code`, `day` AS `day`, `flag` AS `flag`, 'note' AS `metric`, CAST(NULL AS DECIMAL(20,4)) AS `value`, `raw` AS `text` FROM (SELECT `group_id`, `seq`, `code`, `amount`, `other`, `raw`, `day`, `flag` FROM `row_column_source`) dh_unpivot_input) dh_output;;
